/**
 * US-05 — parse_reservation.
 *
 * Extracts the incoming WhatsApp text message from the webhook payload and
 * applies the reservation parsing rules in the specified order:
 *   1) quantity, 2) RUT (captured for the order row and removed from the
 *   medication query), 3) leading intent keywords.
 * Outputs ONE item { phone, query, quantity, rut, text } or an EMPTY array.
 * Never throws: malformed payloads are dropped silently.
 */

/** quantity patterns, tried in the specified order. */
function extractQuantity(text) {
  let m = / x\s*(\d{1,3})\s*$/i.exec(text);
  if (m) return { quantity: parseInt(m[1], 10), matchText: m[0] };
  m = /(\d{1,3})\s*(?:unidades|uds|u)\b/i.exec(text);
  if (m) return { quantity: parseInt(m[1], 10), matchText: m[0] };
  return null;
}

/**
 * Parse a free-text reservation request: quantity -> RUT -> intent keywords.
 * Returns { query, quantity, rut } — never throws.
 */
function parseReservationText(text) {
  const raw = String(text === null || text === undefined ? '' : text).trim();
  let working = raw;

  // 1) quantity — tried on the raw text first (spec order).
  const firstPass = extractQuantity(working);

  // 2) RUT — captured for the order row and removed from the medication query.
  const rutMatch = /\b(\d{1,2}\.?\d{3}\.?\d{3}-[\dkK])\b/i.exec(working);
  const rut = rutMatch ? rutMatch[1] : '';
  if (rutMatch) {
    working = working.replace(rutMatch[0], ' ');
    working = working.replace(/\brut\b/ig, ' '); // "rut" is a field label, not part of the name
  }

  // 1b) quantity retried once the trailing RUT block is gone: users write
  //     "reservar X x2 rut 12.345.678-5" and the end-anchored pattern needs the
  //     RUT removed before it can see the quantity at the end of the string.
  let quantity = firstPass ? firstPass.quantity : null;
  let quantityText = firstPass ? firstPass.matchText : '';
  if (quantity === null) {
    const secondPass = extractQuantity(working);
    if (secondPass) {
      quantity = secondPass.quantity;
      quantityText = secondPass.matchText;
    }
  }
  if (quantityText) working = working.replace(quantityText, ' ');
  if (quantity === null || isNaN(quantity)) quantity = 1;

  // 3) leading intent keywords are stripped, then the remainder is the query.
  working = working.replace(/^\s*(?:(?:reservar|reserva|encargar|encargo|comprar|lo quiero)\s*)+/i, ' ');

  return {
    query: working.replace(/\s+/g, ' ').trim(),
    quantity: quantity,
    rut: rut
  };
}

// --- n8n data assembly (guarded so the test harness can load the functions) ---
const out = [];
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  try {
    const items = $input.all();
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const json = item && item.json ? item.json : item;
      const body = json && json.body ? json.body : json;
      if (!body || !Array.isArray(body.entry)) continue;
      for (let e = 0; e < body.entry.length; e++) {
        const entry = body.entry[e] || {};
        const changes = Array.isArray(entry.changes) ? entry.changes : [];
        for (let c = 0; c < changes.length; c++) {
          const value = (changes[c] && changes[c].value) || {};
          const messages = Array.isArray(value.messages) ? value.messages : [];
          for (let m = 0; m < messages.length; m++) {
            const msg = messages[m];
            if (!msg || msg.type !== 'text') continue;
            const textBody =
              msg.text && typeof msg.text.body === 'string' ? msg.text.body.trim() : '';
            if (!textBody) continue;
            const parsed = parseReservationText(textBody);
            out.push({
              json: {
                phone: msg.from ? String(msg.from) : '',
                query: parsed.query,
                quantity: parsed.quantity,
                rut: parsed.rut,
                text: textBody
              }
            });
            return out; // ONE item per webhook payload
          }
        }
      }
    }
  } catch (err) {
    return []; // malformed payload → drop, never throw
  }
  return out;
}

/**
 * US-04 — Consulta de stock (fuzzy, LLM-free).
 *
 * SCORE = 0.60 * tokenSimilarity + 0.30 * coverage + 0.10 * doseBonus
 *   - tokenSimilarity: mean over query tokens of the best similarity found in the
 *     pool of tokens from nombre_comercial + principio_activo + dosis.
 *     Shortcuts on the candidate token: exact = 1.0, starts with query = 0.92,
 *     contains query = 0.85, otherwise levenshtein similarity.
 *   - coverage: fraction of query tokens whose best similarity is >= COVERAGE_TOKEN_MIN.
 *   - doseBonus: 1 (row dose matches the query dose token), 0.5 (query has no dose
 *     token), 0 (query dose missing in the row); a missing dose also multiplies the
 *     final score by DOSE_PENALTY (0.6).
 *   - Dose tokens are excluded from tokenSimilarity/coverage: the dose axis is
 *     scored only through doseBonus/penalty, because sheet doses are spaced
 *     ("75 mg") while users type "75mg" and a literal token match would
 *     double-penalize a correct query.
 *   - MATCH_THRESHOLD = 0.72 decides a match; MAX_SUGGESTIONS = 3 caps the
 *     bioequivalent fallback list (RF-02).
 *
 * DELIBERATELY LLM-FREE: no Gemini/LLM node exists in this workflow, so RF-01
 * grounding (never invent names, prices or stock) is structural — every figure
 * in the reply is read from the sheets and recomputed here.
 *
 * LATENCY NOTE (risk R-01): the two Google Sheets reads (read_catalogo +
 * read_inventario) dominate end-to-end latency; caching the catalog in the
 * workflow is the planned optimization.
 */

const COVERAGE_TOKEN_MIN = 0.799;
const MATCH_THRESHOLD = 0.72;
const MAX_SUGGESTIONS = 3;
const DOSE_PENALTY = 0.6;

function normalize(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function tokenize(s) {
  const n = normalize(s);
  return n ? n.split(' ') : [];
}

function levenshteinDistance(a, b) {
  a = String(a === null || a === undefined ? '' : a);
  b = String(b === null || b === undefined ? '' : b);
  if (a === b) return 0;
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  let prev = new Array(b.length + 1);
  let curr = new Array(b.length + 1);
  for (let j = 0; j <= b.length; j++) prev[j] = j;
  for (let i = 1; i <= a.length; i++) {
    curr[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      curr[j] = Math.min(curr[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }
  return prev[b.length];
}

function levenshteinSimilarity(a, b) {
  const left = String(a === null || a === undefined ? '' : a);
  const right = String(b === null || b === undefined ? '' : b);
  if (left.length === 0 && right.length === 0) return 1;
  if (left.length === 0 || right.length === 0) return 0;
  const maxLen = Math.max(left.length, right.length);
  return 1 - levenshteinDistance(left, right) / maxLen;
}

function isDoseToken(token) {
  return /^\d+(\.\d+)?$/.test(token) || /^\d+(\.\d+)?(mg|ml|g|ui|mcg)$/.test(token);
}

function parseDoseToken(token) {
  const m = /^(\d+(?:\.\d+)?)(mg|ml|g|ui|mcg)?$/.exec(String(token));
  return m ? { value: m[1], unit: m[2] || '' } : null;
}

/** Row dose matches the query dose token when the normalized dose tokens contain
 *  the token value (and the unit, when the token carries one), e.g. dose
 *  "75 mg" contains token "75" and token "75mg". */
function rowDoseMatches(rowDose, doseToken) {
  const parsed = parseDoseToken(doseToken);
  if (!parsed) return false;
  const doseTokens = tokenize(rowDose);
  if (doseTokens.indexOf(parsed.value) === -1) return false;
  if (!parsed.unit) return true;
  return doseTokens.indexOf(parsed.unit) !== -1;
}

/** Field-match shortcuts: exact = 1.0, starts with query = 0.92, contains = 0.85. */
function tokenSimilarity(queryToken, candidateToken) {
  if (queryToken === candidateToken) return 1;
  if (queryToken.length > 0 && candidateToken.indexOf(queryToken) === 0) return 0.92;
  if (queryToken.length > 0 && candidateToken.indexOf(queryToken) !== -1) return 0.85;
  return levenshteinSimilarity(queryToken, candidateToken);
}

function rowJson(item) {
  return item && item.json ? item.json : item;
}

function tokenPool(row) {
  const fields = [row.nombre_comercial, row.principio_activo, row.dosis]
    .map(normalize)
    .join(' ')
    .trim();
  return fields ? fields.split(' ') : [];
}

function isActiveRow(row) {
  return !!row && normalize(row.activo) === 'si';
}

/** Final score (0..1) of one catalog row for the given tokenized query. */
function scoreCandidate(queryTokens, queryDoseToken, row) {
  const pool = tokenPool(row);
  let sum = 0;
  let covered = 0;
  let scored = 0;
  for (let i = 0; i < queryTokens.length; i++) {
    const qt = queryTokens[i];
    if (isDoseToken(qt)) continue; // dose axis is scored via doseBonus/penalty only
    scored++;
    let best = 0;
    for (let j = 0; j < pool.length; j++) {
      const s = tokenSimilarity(qt, pool[j]);
      if (s > best) best = s;
    }
    sum += best;
    if (best >= COVERAGE_TOKEN_MIN) covered++;
  }
  const ts = scored ? sum / scored : 0;
  const coverage = scored ? covered / scored : 0;
  const doseMatched = queryDoseToken ? rowDoseMatches(row.dosis, queryDoseToken) : null;
  const doseBonus = queryDoseToken ? (doseMatched ? 1 : 0) : 0.5;
  let final = 0.60 * ts + 0.30 * coverage + 0.10 * doseBonus;
  if (queryDoseToken && !doseMatched) final *= DOSE_PENALTY;
  return final;
}

function inventoryMap(inventoryRows) {
  const map = new Map();
  const rows = inventoryRows || [];
  for (let i = 0; i < rows.length; i++) {
    const r = rowJson(rows[i]);
    if (r && r.medicamento_id !== undefined && r.medicamento_id !== null) {
      map.set(normalize(r.medicamento_id), r);
    }
  }
  return map;
}

/** stock_neto is ALWAYS recomputed here (stock_real - stock_reservado);
 *  the sheet's stock_neto formula column is never trusted. */
function stockNeto(row, inventoryById) {
  const inv = inventoryById.get(normalize(row.medicamento_id));
  if (!inv) return 0;
  const real = Number(inv.stock_real);
  const reserved = Number(inv.stock_reservado);
  return (isNaN(real) ? 0 : real) - (isNaN(reserved) ? 0 : reserved);
}

/**
 * Best active catalog row for a free-text query.
 * Returns { matched, score }: `matched` is the row only when score >= MATCH_THRESHOLD,
 * `score` is always the best score found (so callers/tests can assert on it).
 */
function matchMedicine(query, catalogRows) {
  const queryTokens = tokenize(query);
  let queryDoseToken = null;
  for (let i = 0; i < queryTokens.length; i++) {
    if (isDoseToken(queryTokens[i])) {
      queryDoseToken = queryTokens[i];
      break;
    }
  }
  const rows = (catalogRows || []).map(rowJson).filter(isActiveRow);
  let bestRow = null;
  let bestScore = 0;
  for (let i = 0; i < rows.length; i++) {
    const s = scoreCandidate(queryTokens, queryDoseToken, rows[i]);
    if (bestRow === null || s > bestScore) {
      bestRow = rows[i];
      bestScore = s;
    }
  }
  return {
    matched: bestRow !== null && bestScore >= MATCH_THRESHOLD ? bestRow : null,
    score: bestScore
  };
}

/** CLP with "." thousands separator and "$" prefix, e.g. formatClp(4500) === "$4.500". */
function formatClp(value) {
  const n = Math.round(Number(value) || 0);
  const digits = String(Math.abs(n));
  let grouped = '';
  for (let i = 0; i < digits.length; i++) {
    grouped += digits.charAt(i);
    const remaining = digits.length - 1 - i;
    if (remaining > 0 && remaining % 3 === 0) grouped += '.';
  }
  return (n < 0 ? '-' : '') + '$' + grouped;
}

/** Up to MAX_SUGGESTIONS active rows with stock: bioequivalente_de points at the
 *  matched row, OR same principio_activo AND same dosis (RF-02 fallback). */
function suggestionRows(matched, catalogRows, inventoryById) {
  const matchedId = normalize(matched.medicamento_id);
  const matchedActive = normalize(matched.principio_activo);
  const matchedDose = normalize(matched.dosis);
  const rows = (catalogRows || []).map(rowJson);
  const out = [];
  for (let i = 0; i < rows.length; i++) {
    const cand = rows[i];
    if (!isActiveRow(cand)) continue;
    if (normalize(cand.medicamento_id) === matchedId) continue;
    const byLink = normalize(cand.bioequivalente_de) === matchedId;
    const byMoiety =
      normalize(cand.principio_activo) === matchedActive &&
      normalize(cand.dosis) === matchedDose;
    if (!byLink && !byMoiety) continue;
    if (stockNeto(cand, inventoryById) <= 0) continue;
    out.push(cand);
    if (out.length >= MAX_SUGGESTIONS) break;
  }
  return out;
}

/**
 * Full Spanish reply for a query. Returns '' when nothing should be sent
 * (empty/non-text input). Never invents names, prices or stock numbers (RF-01).
 */
function buildReplyText(query, catalogRows, inventoryRows) {
  const q = String(query === null || query === undefined ? '' : query).trim();
  if (!q || !normalize(q)) return '';
  const inventoryById = inventoryMap(inventoryRows);
  const result = matchMedicine(q, catalogRows);

  if (result.matched) {
    const row = result.matched;
    const stock = stockNeto(row, inventoryById);
    const head =
      row.nombre_comercial + ' ' + row.dosis + ' — ' +
      formatClp(row.precio_unitario_clp) + ' c/u. Stock disponible: ' + stock + ' unidades.';
    if (stock > 0) return head;

    const alts = suggestionRows(row, catalogRows, inventoryById);
    if (alts.length === 0) {
      // No available bioequivalent: state it plainly, without naming any product.
      return 'Este producto no tiene stock disponible en este momento y no contamos con bioequivalentes disponibles con stock. Puede intentar nuevamente más tarde.';
    }
    let text =
      head + ' Producto agotado temporalmente. Bioequivalentes disponibles con stock:\n';
    for (let i = 0; i < alts.length; i++) {
      const a = alts[i];
      text +=
        '- ' + a.nombre_comercial + ' ' + a.dosis + ' — ' +
        formatClp(a.precio_unitario_clp) + ' c/u.\n';
    }
    return text.replace(/\n$/, '');
  }

  // No match (R-02 grounding): no product name, no price, no stock figure.
  return 'No encontré "' + q + '" en nuestro catálogo. Le sugiero reintentar con el nombre del principio activo (el genérico).';
}


// --- US-05 reservation logic -------------------------------------------------
// NOTE ON DUPLICATION: the fuzzy matcher above is intentionally duplicated from
// workflows/US-04-consulta-stock.json — n8n cannot import local JS without
// allowlisting a folder, so each workflow carries its own copy.
// scripts/test-reserva.mjs is the DRIFT GUARD that keeps both copies honest.
//
// RF-03: every confirmed request generates a sequential code FAR-XXXX (shown as
//        #FAR-XXXX) linked to the customer's phone and RUT.
// RF-04: creating an order immediately increments inventario.stock_reservado.
// RNF-04: reservation writes are sequential and verified after the write.
// D-01 (PROVISIONAL — pending validation with bodega, see
//        docs/google-sheets-schema.md): requiere_receta = "SI" is born in
//        PENDIENTE_RECETA with fecha_expiracion = fecha_creacion + 12h;
//        requiere_receta = "NO" is born in EN_PREPARACION with no expiry.
//        Only enum states from setup-sheets.gs are ever produced.

const RECIPE_EXPIRY_HOURS = 12;
const ESTADO_PENDIENTE_RECETA = 'PENDIENTE_RECETA';
const ESTADO_EN_PREPARACION = 'EN_PREPARACION';
const BITACORA_ACCION_RESERVA = 'RESERVA_ALTA';
const CONFLICTO_FLAG = 'CONFLICTO_INVENTARIO';
const MILLISECONDS_PER_HOUR = 60 * 60 * 1000;

/** quantity patterns, tried in the specified order. */
function extractQuantity(text) {
  let m = / x\s*(\d{1,3})\s*$/i.exec(text);
  if (m) return { quantity: parseInt(m[1], 10), matchText: m[0] };
  m = /(\d{1,3})\s*(?:unidades|uds|u)\b/i.exec(text);
  if (m) return { quantity: parseInt(m[1], 10), matchText: m[0] };
  return null;
}

/**
 * Parse a free-text reservation request: quantity -> RUT -> intent keywords.
 * Returns { query, quantity, rut } — never throws. Same copy as parse_reservation.
 */
function parseReservationText(text) {
  const raw = String(text === null || text === undefined ? '' : text).trim();
  let working = raw;
  const firstPass = extractQuantity(working);
  const rutMatch = /\b(\d{1,2}\.?\d{3}\.?\d{3}-[\dkK])\b/i.exec(working);
  const rut = rutMatch ? rutMatch[1] : '';
  if (rutMatch) {
    working = working.replace(rutMatch[0], ' ');
    working = working.replace(/\brut\b/ig, ' ');
  }
  let quantity = firstPass ? firstPass.quantity : null;
  let quantityText = firstPass ? firstPass.matchText : '';
  if (quantity === null) {
    const secondPass = extractQuantity(working);
    if (secondPass) {
      quantity = secondPass.quantity;
      quantityText = secondPass.matchText;
    }
  }
  if (quantityText) working = working.replace(quantityText, ' ');
  if (quantity === null || isNaN(quantity)) quantity = 1;
  working = working.replace(/^\s*(?:(?:reservar|reserva|encargar|encargo|comprar|lo quiero)\s*)+/i, ' ');
  return {
    query: working.replace(/\s+/g, ' ').trim(),
    quantity: quantity,
    rut: rut
  };
}

/**
 * RF-03 — sequential code: trailing digits of every codigo_far, max + 1, padded
 * to 4 digits. Empty or all-unparseable lists yield FAR-0001; malformed codes
 * are ignored for the max computation and never crash.
 */
function nextOrderCode(existingCodes) {
  const list = Array.isArray(existingCodes) ? existingCodes : [];
  let max = 0;
  for (let i = 0; i < list.length; i++) {
    const m = /(\d+)$/.exec(String(list[i] === null || list[i] === undefined ? '' : list[i]).trim());
    if (!m) continue; // non-numeric / malformed codes are ignored, never fatal
    const n = parseInt(m[1], 10);
    if (isNaN(n)) continue;
    if (n > max) max = n;
  }
  const digits = String(max + 1);
  const padded = digits.length >= 4 ? digits : ('0000' + digits).slice(-4);
  return 'FAR-' + padded;
}

/**
 * RF-04 / RNF-04 — available = stock_real - stock_reservado, computed here;
 * the sheet's stock_neto column is NEVER trusted.
 * reason: AGOTADO (nothing left; the caller uses the US-04 agotamiento wording)
 *         INSUFICIENTE (message states the exact remaining count).
 */
function validateStock(quantity, invRow, productLabel) {
  const inv = invRow || {};
  const real = Number(inv.stock_real);
  const reserved = Number(inv.stock_reservado);
  const available = (isNaN(real) ? 0 : real) - (isNaN(reserved) ? 0 : reserved);
  const qty = Number(quantity);
  if (available <= 0) {
    return { ok: false, reason: 'AGOTADO', available: available, message: '' };
  }
  if (qty > available) {
    const label = productLabel ? ' de ' + productLabel : '';
    return {
      ok: false,
      reason: 'INSUFICIENTE',
      available: available,
      message:
        'Stock insuficiente' + label + ': solo quedan ' + available +
        ' unidades disponibles. Puede reservar hasta ' + available + ' unidades.'
    };
  }
  return { ok: true, reason: '', available: available, message: '' };
}

/**
 * D-01 (PROVISIONAL, pending validation with bodega) — initial order state.
 * requiere_receta = "SI" -> PENDIENTE_RECETA, expires fecha_creacion + 12h.
 * requiere_receta = "NO" -> EN_PREPARACION, no expiry.
 * Only enum states declared in setup-sheets.gs are ever produced.
 */
function initialStateFor(requiereReceta, fechaCreacion) {
  const fecha = fechaCreacion || new Date().toISOString();
  if (normalize(requiereReceta) === 'si') {
    const expira = new Date(Date.parse(fecha) + RECIPE_EXPIRY_HOURS * MILLISECONDS_PER_HOUR).toISOString();
    return { estado: ESTADO_PENDIENTE_RECETA, fecha_expiracion: expira };
  }
  return { estado: ESTADO_EN_PREPARACION, fecha_expiracion: null };
}

/**
 * RF-03 — final WhatsApp copy (neutral professional Spanish; R-02 grounding:
 * every figure comes from the catalog/inventory rows, nothing is invented).
 */
function buildReservationReply(orderRow, catalogRow) {
  const head =
    'Reserva confirmada. Tu código es #' + orderRow.codigo_far + ' — ' +
    catalogRow.nombre_comercial + ' ' + catalogRow.dosis + ' x' + orderRow.cantidad + ', ' +
    formatClp(orderRow.precio_total_clp) + ' en total.';
  if (normalize(catalogRow.requiere_receta) === 'si') {
    return head +
      ' Su pedido quedó reservado por 12 horas. Envíe la foto de su receta médica al WhatsApp de la farmacia indicando este código.';
  }
  return head + ' No requiere receta, ya pasó a preparación.';
}

/**
 * RF-03 / RF-04 — builds every write payload for one confirmed reservation:
 * the ordenes row, the updated inventario row (stock_reservado + cantidad), the
 * bitacora row and the expected post-write value used by the RNF-04 verification.
 */
function buildCommitPayload(parsed, matchedRow, invRow, existingCodes, fechaCreacion) {
  const p = parsed || {};
  const quantity = Number(p.quantity) > 0 ? Math.floor(Number(p.quantity)) : 1;
  const code = nextOrderCode(existingCodes);
  const fecha = fechaCreacion || new Date().toISOString();
  const initial = initialStateFor(matchedRow.requiere_receta, fecha);
  const unit = Number(matchedRow.precio_unitario_clp);
  const total = (isNaN(unit) ? 0 : unit) * quantity;
  const current = Number(invRow.stock_reservado);
  const currentSafe = isNaN(current) ? 0 : current;
  const expected = currentSafe + quantity;

  const order_row = {
    codigo_far: code,
    fecha_creacion: fecha,
    rut: p.rut ? p.rut : '',
    telefono: p.phone ? String(p.phone) : '',
    nombre_cliente: '', // WhatsApp gives phone + RUT only; the name is never invented
    medicamento_id: matchedRow.medicamento_id,
    cantidad: quantity,
    precio_total_clp: total,
    estado: initial.estado,
    url_receta: '',
    fecha_receta: '',
    fecha_expiracion: initial.fecha_expiracion ? initial.fecha_expiracion : '',
    notas: ''
  };

  const inventory_row = {
    medicamento_id: matchedRow.medicamento_id,
    stock_real: Number(invRow.stock_real),
    stock_reservado: expected, // RF-04: immediate increment
    ultima_actualizacion: fecha
  };

  const bitacora_row = {
    timestamp: fecha,
    accion: BITACORA_ACCION_RESERVA,
    codigo_far: code,
    medicamento_id: matchedRow.medicamento_id,
    delta_reservado: quantity,
    detalle: 'Reserva inmediata US-05; stock_reservado ' + currentSafe + ' -> ' + expected
  };

  return {
    code: code,
    order_row: order_row,
    inventory_row: inventory_row,
    bitacora_row: bitacora_row,
    expected_reservado: expected,
    message: buildReservationReply(order_row, matchedRow)
  };
}

/**
 * Produces the ONE item consumed by the IF branch and the write nodes.
 * decision = REJECT (nothing to write, message already final)
 *         |  COMMIT (code + order_row + inventory_row + bitacora_row + expected_reservado).
 */
function evaluateReservation(parsed, catalogRows, inventoryRows, orderRows) {
  const p = parsed || {};
  const phone = p.phone ? String(p.phone) : '';
  const query = p.query ? String(p.query) : '';
  const quantity = Number(p.quantity) > 0 ? Math.floor(Number(p.quantity)) : 1;
  const reject = {
    phone: phone,
    decision: 'REJECT',
    code: '',
    order_row: null,
    inventory_row: null,
    bitacora_row: null,
    expected_reservado: null,
    message: ''
  };

  if (!phone || !normalize(query)) {
    reject.message =
      'Para generar una reserva indique qué medicamento desea reservar (nombre comercial o principio activo).';
    return reject;
  }

  const match = matchMedicine(query, catalogRows);
  if (!match.matched) {
    reject.message = buildReplyText(query, catalogRows, inventoryRows); // grounded: no name, no price, no stock
    return reject;
  }

  const row = match.matched;
  const inv = inventoryMap(inventoryRows).get(normalize(row.medicamento_id)) || null;
  if (!inv) {
    reject.message = buildReplyText(query, catalogRows, inventoryRows);
    return reject;
  }

  const label = row.nombre_comercial + ' ' + row.dosis;
  const stock = validateStock(quantity, inv, label);
  if (!stock.ok) {
    // AGOTADO reuses the exact US-04 agotamiento + bioequivalentes wording.
    reject.message =
      stock.reason === 'AGOTADO'
        ? buildReplyText(query, catalogRows, inventoryRows)
        : stock.message;
    return reject;
  }

  const codes = [];
  const orders = orderRows || [];
  for (let i = 0; i < orders.length; i++) codes.push(rowJson(orders[i]).codigo_far);

  const payload = buildCommitPayload(p, row, inv, codes, new Date().toISOString());
  return {
    phone: phone,
    decision: 'COMMIT',
    code: payload.code,
    order_row: payload.order_row,
    inventory_row: payload.inventory_row,
    bitacora_row: payload.bitacora_row,
    expected_reservado: payload.expected_reservado,
    message: payload.message
  };
}

/**
 * RNF-04 — post-write verification: does the re-read of `inventario` show the
 * expected stock_reservado for this medicamento_id?
 * CONCURRENCY NOTE (risk R-01): this closes the read-write-verify loop for ONE
 * execution. True cross-request serialization needs n8n queue mode + Redis and
 * is deferred to US-13; until then two simultaneous reservations of the last
 * unit can still interleave between the read and the update.
 */
function verifyReservation(expectedReservado, reReadRows, medicamentoId) {
  const rows = reReadRows || [];
  let found = null;
  for (let i = 0; i < rows.length; i++) {
    const r = rowJson(rows[i]);
    if (r && normalize(r.medicamento_id) === normalize(medicamentoId)) {
      found = r;
      break;
    }
  }
  const expected = Number(expectedReservado);
  const actual = found ? Number(found.stock_reservado) : NaN;
  const ok = found !== null && !isNaN(actual) && actual === expected;
  return { ok: ok, conflict: !ok, actual: found ? actual : null, expected: expected };
}

// --- n8n data assembly -------------------------------------------------------
// Guarded: outside the editor (test harness) `$`/`$input` do not exist, so this
// block stays inert and only the named functions above are reachable.
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  let raw = null;
  try {
    raw = $('parse_reservation').first().json;
  } catch (err) {
    raw = null;
  }
  if (!raw) return []; // no parsed message -> nothing to evaluate, nothing to send
  // Re-parse the raw text so this node owns the runtime copy of the parser
  // (the parse node exposes { phone, query, quantity, rut } as specified).
  const parsed = raw.text ? parseReservationText(raw.text) : raw;
  const catalogRows = $('read_catalogo').all();
  const inventoryRows = $('read_inventario').all();
  const orderRows = $input.all(); // read_ordenes feeds this node directly
  return [{ json: evaluateReservation(parsed, catalogRows, inventoryRows, orderRows) }];
}

/**
 * US-05 — finalize_reply.
 *
 * REJECT items already carry the final message (nothing was written) and are
 * forwarded untouched. COMMIT items are verified against the post-write re-read
 * of `inventario` (RNF-04): a mismatch is NEVER silent — the reply is flagged
 * with CONFLICTO_INVENTARIO so the customer and the pharmacy both see it.
 */
function normalize(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function rowJson(item) {
  return item && item.json ? item.json : item;
}

/**
 * RNF-04 — compares the expected stock_reservado against the re-read rows.
 * Returns { ok, conflict, actual, expected }; a missing row counts as a conflict.
 * Cross-request serialization (queue mode + Redis) is deferred to US-13 (risk R-01).
 */
function verifyReservation(expectedReservado, reReadRows, medicamentoId) {
  const rows = reReadRows || [];
  let found = null;
  for (let i = 0; i < rows.length; i++) {
    const r = rowJson(rows[i]);
    if (r && normalize(r.medicamento_id) === normalize(medicamentoId)) {
      found = r;
      break;
    }
  }
  const expected = Number(expectedReservado);
  const actual = found ? Number(found.stock_reservado) : NaN;
  const ok = found !== null && !isNaN(actual) && actual === expected;
  return { ok: ok, conflict: !ok, actual: found ? actual : null, expected: expected };
}

// --- n8n data assembly -------------------------------------------------------
// Guarded: outside the editor (test harness) `$`/`$input` do not exist, so this
// block stays inert and only the named functions above are reachable.
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  const ev = $('evaluate_reservation').first().json;
  if (!ev || ev.decision !== 'COMMIT') {
    // REJECT: the message was already built by evaluate_reservation.
    return [{ json: { phone: ev ? ev.phone : '', message: ev ? ev.message : '', conflict: false } }];
  }
  const check = verifyReservation(ev.expected_reservado, $input.all(), ev.inventory_row.medicamento_id);
  let message = ev.message;
  if (!check.ok) {
    message +=
      '\n\nAviso: CONFLICTO_INVENTARIO — la verificación posterior a la escritura no confirmó el stock reservado esperado (' +
      ev.expected_reservado + ' unidades). El inventario será revisado manualmente. Disculpe las molestias.';
  }
  return [{ json: { phone: ev.phone, message: message, conflict: !check.ok } }];
}
